select p.user_id::uuid, p.date::date, s.slot::smallint, substr(p.pattern, s.slot + 1, 1)::smallint,

       case substr(p.pattern, s.slot + 1, 1)
         when '1' then (case p.user_id
            when '11111111-1111-4111-8111-111111111101' then (array['gamma research','lab work','avoiding stress'])[1 + (s.slot % 3)]
            when '11111111-1111-4111-8111-111111111102' then (array['suit R&D','arc reactor v52','avoiding board meetings'])[1 + (s.slot % 3)]
            when '11111111-1111-4111-8111-111111111103' then 'royal duties'
            when '11111111-1111-4111-8111-111111111104' then (array['helping old ladies','shield duty','motivational posters'])[1 + (s.slot % 3)]
            when '11111111-1111-4111-8111-111111111106' then (array['spreadsheets','emails','meeting'])[1 + (s.slot % 3)]
            else '████ classified' end)
         when '2' then (case p.user_id
            when '11111111-1111-4111-8111-111111111101' then 'calming yoga'
            when '11111111-1111-4111-8111-111111111102' then 'suit cardio'
            when '11111111-1111-4111-8111-111111111103' then 'hammer training'
            when '11111111-1111-4111-8111-111111111104' then 'on your left'
            else 'sparring' end)
         when '6' then (case p.user_id
            when '11111111-1111-4111-8111-111111111101' then 'SMASH'
            when '11111111-1111-4111-8111-111111111102' then 'lab youtube spiral'
            when '11111111-1111-4111-8111-111111111103' then 'Midgardian television'
            else 'doomscrolling' end)
         when '3' then (case p.user_id when '11111111-1111-4111-8111-111111111103' then 'tavern' when '11111111-1111-4111-8111-111111111102' then 'gala' else 'friends' end)
         when '4' then (case p.user_id when '11111111-1111-4111-8111-111111111101' then 'fleeing the scene' else 'travel' end)
         when '7' then (case p.user_id when '11111111-1111-4111-8111-111111111103' then 'FEAST' else null end)
         else null
       end
from p cross join (select generate_series(0, 95) as slot) s;

